var e={name:"Soumya Kumar Mallick",firstName:"Soumya Kumar",lastName:"Mallick",title:"Senior Frontend Developer",tagline:"Angular & React.js | TypeScript | Enterprise Web Applications",roles:["Senior Frontend Developer","Angular Specialist","React.js Developer","TypeScript Enthusiast","Enterprise UI Architect"],summary:"Frontend Developer with 5+ years of experience designing, building, and optimizing enterprise-scale web applications using Angular, React.js, and TypeScript. Proven track record delivering a mission-critical payment module end-to-end for a Central Government (Ministry of Road Transport & Highways) platform, including secure payment gateway integration, transaction verification, and REST API integration. Skilled in reactive UI architecture, performance optimization, cross-browser compatibility, and leading development teams in Agile environments. Adept at translating complex business requirements into scalable, maintainable, and high-performance frontend solutions.",email:"soumya27mallick01@gmail.com",emailHref:"mailto:soumya27mallick01@gmail.com",location:"India",linkedin:"https://www.linkedin.com/in/soumya-kumar-mallick-07b5921b3/",github:"https://github.com/soumya27mallick01",resumeUrl:"assets/resume/SoumyaKumarMallick_Resume.pdf"},t=[{value:5,suffix:"+",label:"Years of Experience"},{value:4,suffix:"",label:"Platforms Delivered"},{value:3,suffix:"",label:"Government Platforms"},{value:20,suffix:"+",label:"Technologies"}];var i=[{name:"NextGen eChallan",tagline:"Citizen-facing traffic enforcement platform for the Ministry of Road Transport & Highways",category:"Government Platform",period:"Sep 2025 \u2013 Present",overview:"A Central Government initiative for MoRTH spanning Manual Challan, Grievance Redressal, Vehicle History, Challan History, Role Management, Offence Management, Mobile Device Manager, Payment, and Dashboard modules.",responsibilities:["Developed platform modules serving citizens and enforcement authorities.","Implemented secure transaction flows and session management.","Built complex Reactive Forms with multi-field validation.","Diagnosed and resolved production issues for a live government platform."],features:["Manual Challan","Grievance Redressal","Vehicle & Challan History","Role & Offence Management","Mobile Device Manager","Payment & Dashboard Modules"],challenges:"Safeguarding sensitive payment data and maintaining stability across a high-traffic live government platform with complex multi-field citizen-facing forms.",solutions:"Secure transaction flows, session management, and validated Reactive Forms; production issue diagnosis and rapid resolution to sustain reliability.",technologies:["Angular","TypeScript","RxJS","REST APIs","Docker","GitHub"],demoUrl:"",githubUrl:"",accent:"#0891B2"},{name:"NICSI-ERP",tagline:"In-house enterprise resource planning system for customer and vendor operations",category:"Enterprise ERP",period:"Sep 2023 \u2013 Aug 2025",overview:"An in-house ERP managing customer and vendor operations via NICSI, spanning multiple interrelated modules \u2014 with a legacy-to-React migration and measurable performance gains.",responsibilities:["Built and scaled an ERP managing customer and vendor operations.","Architected legacy module migration to React.js with maximum uptime.","Delivered performance optimizations improving page load speed.","Built JS Chart data visualizations for resource allocation.","Integrated RESTful APIs with backend engineers."],features:["Customer & vendor operations","Legacy-to-React.js migration","JS Chart data visualization","Performance-optimized modules"],challenges:"Migrating legacy modules to React.js without downtime while preserving maximum system uptime on a live ERP.",solutions:"Phased, architecture-led migration with high maintainability, plus targeted performance optimizations and RESTful API integration.",technologies:["React.js","Redux","TypeScript","JS Chart","Docker","GitLab","TailwindCSS"],demoUrl:"",githubUrl:"",accent:"#0891B2"},{name:"CCI ERP \u2014 MKTM Module",tagline:"Marketing and Transport Module for Cement Corporation of India",category:"Government ERP",period:"May 2023 \u2013 Aug 2023",overview:"The Marketing and Transport Module (MKTM) manages sales and transport operations for Cement Corporation of India (CCI), integrated with the broader CCI ERP ecosystem.",responsibilities:["Developed sales and transport management workflows.","Built robust, reusable Angular components reducing bug count.","Delivered a dynamic, accessible frontend on Angular CLI 14.","Participated in bi-weekly Scrum ceremonies and sprint planning."],features:["Sales operations management","Transport operations management","Reusable enterprise Angular components"],challenges:"Delivering an accessible, dynamic frontend with reusable components under tight enterprise timelines.",solutions:"Reusable Angular component library on Angular CLI 14 with accessibility baked in, delivered through disciplined Scrum ceremonies.",technologies:["Angular","TypeScript","JavaScript","JS Chart","HTML5","Bootstrap","CSS3"],demoUrl:"",githubUrl:"",accent:"#22D3EE"},{name:"Port Operation Management System",tagline:"Integrated platform for Chennai Port Trust (ChPT) end-to-end port operations",category:"Government Platform",period:"Jul 2021 \u2013 Apr 2023",overview:"An integrated platform overseeing end-to-end port operations for Chennai Port Trust, with internal tooling and client-facing interactive components.",responsibilities:["Contributed to an integrated platform overseeing end-to-end port operations.","Built internal tools using Java Server Faces (JSF) and PostgreSQL.","Developed interactive UI components improving usability for operational staff."],features:["End-to-end port operation workflows","JSF + PostgreSQL internal tools","Interactive operational UI components"],challenges:"Supporting complex, high-stakes port workflows with tooling that operational staff can use reliably.",solutions:"Purpose-built JSF and PostgreSQL internal tools paired with intuitive interactive UI components.",technologies:["JSF","PostgreSQL","JavaScript","HTML5","CSS3"],demoUrl:"",githubUrl:"",accent:"#0E7490"}],a=[{title:"Frameworks & Libraries",description:"Core application development with modern JavaScript frameworks.",skills:[{name:"Angular",level:95,icon:"angular"},{name:"React.js",level:90,icon:"react"},{name:"TypeScript",level:92,icon:"typescript"},{name:"JavaScript (ES6+)",level:90,icon:"javascript"}]},{title:"Markup & Styling",description:"Pixel-perfect, responsive, and accessible user interfaces.",skills:[{name:"HTML5",level:95,icon:"html5"},{name:"CSS3",level:92,icon:"css3"},{name:"SCSS",level:88,icon:"sass"},{name:"TailwindCSS",level:85,icon:"tailwind"},{name:"Bootstrap",level:85,icon:"bootstrap"}]},{title:"State Management",description:"Reactive, predictable state across enterprise applications.",skills:[{name:"Redux",level:85,icon:"redux"},{name:"NgRx",level:85,icon:"layers"},{name:"RxJS",level:88,icon:"activity"}]},{title:"Testing",description:"Confidence through automated unit testing.",skills:[{name:"Jasmine",level:80,icon:"shield"},{name:"Karma",level:80,icon:"flask"}]},{title:"Tools & Workflow",description:"Professional development workflow and delivery tooling.",skills:[{name:"Docker",level:75,icon:"docker"},{name:"Git",level:90,icon:"git"},{name:"GitHub",level:90,icon:"github"},{name:"GitLab",level:85,icon:"gitlab"},{name:"Postman",level:85,icon:"postman"},{name:"JS Chart",level:82,icon:"chart"}]}];var n=[{degree:"Master in Computer Application",institution:"Vidyasagar University",period:"Sep 2017 \u2013 Sep 2020",location:"Medinipur, India",score:"Marks: 75.80%"},{degree:"Bachelor of Computer Application",institution:"JIS College of Engineering",period:"Jul 2014 \u2013 Aug 2017",location:"Kalyani, India",score:"DGPA: 7.96 / 10"}];var o=[{slug:"building-enterprise-angular-applications",title:"Building Enterprise-Grade Angular Applications",excerpt:"Architecture patterns, signals, and component design that keep large Angular applications scalable and maintainable.",category:"Angular",date:"2026-05-10",readTime:"6 min read",tags:["Angular","Architecture","Signals"],demo:!0,body:["Enterprise Angular applications demand more than component libraries \u2014 they demand deliberate architecture. Over 5+ years building government and enterprise platforms, a few principles consistently separate maintainable codebases from legacy traps.","Start with a domain-driven folder structure. Keep features isolated, shared code in shared modules, and models as the single source of truth. When business requirements change \u2014 and they always do \u2014 you want to touch one file, not ten.","Embrace signals for local and global state. Angular signals make state flow explicit and predictable, and combined with OnPush change detection they keep performance predictable even as the component tree grows.","Write reactive forms for anything data-driven. Multi-field validation on citizen-facing workflows is far easier to reason about with typed form models and explicit validators.","Finally, invest in code review culture. Reviewing is where architecture debates happen and where junior developers learn. It is the cheapest performance optimization available to a team."]},{slug:"angular-to-react-migration-lessons",title:"From Angular to React: Lessons from a Legacy Migration",excerpt:"How we migrated legacy ERP modules to React.js while sustaining maximum uptime on a live system.",category:"React",date:"2025-08-02",readTime:"5 min read",tags:["React","Migration","TypeScript"],demo:!0,body:["Migrating a live ERP to React.js is a marathon, not a sprint. The critical constraint was uptime \u2014 end users could not wait while we rebuilt their tools.","We migrated module by module behind feature flags, keeping the legacy system authoritative until each replacement passed parity checks. TypeScript gave us the confidence to refactor aggressively.","Redux provided predictable state that mirrored the business model, while a shared component library kept UI consistent across old and new surfaces.","The result was a codebase that was easier to maintain, faster to extend, and measurably quicker to load \u2014 with zero downtime for the operations relying on it."]},{slug:"mastering-typescript-scalable-frontends",title:"Mastering TypeScript for Scalable Frontend Codebases",excerpt:"Types are the documentation that never goes stale \u2014 patterns for modeling complex domains with TypeScript.",category:"TypeScript",date:"2025-05-19",readTime:"5 min read",tags:["TypeScript","Best Practices"],demo:!0,body:["TypeScript is where scalable frontend codebases are won or lost. Strong typing is a safety net that lets teams move fast without breaking things.","Model your domain first. A payment transaction is not a loosely-typed object \u2014 it has a lifecycle, states, and invariants. Explicit unions and discriminated types turn impossible states into compile errors.","Prefer inference when it is obvious, and be explicit where it matters \u2014 especially at API boundaries where JSON arrives untyped.","Treat strict mode as non-negotiable. The small cost of writing types is repaid many times over in refactoring safety and onboarding speed."]},{slug:"frontend-architecture-government-platforms",title:"Frontend Architecture Patterns for Government Platforms",excerpt:"Reliability, accessibility, and security patterns for public-sector web platforms that millions rely on.",category:"Architecture",date:"2025-03-08",readTime:"7 min read",tags:["Architecture","Accessibility","Security"],demo:!0,body:["Government platforms carry unique responsibilities: millions of users, strict accessibility mandates, and security requirements where a mistake is not a bug but a breach.","Security starts in the frontend: session management, secure transaction flows, and never trusting client-side data without server validation. For payment flows, every step from initiation to verification must be traceable.","Accessibility is non-negotiable \u2014 keyboard navigation, semantic structure, and screen-reader support are core features, not polish items.","Performance is a public service. On constrained connections, every kilobyte matters. Lazy loading, deferred sections, and lean bundles are standard practice, not optimization afterthoughts."]},{slug:"performance-optimization-enterprise-dashboards",title:"Performance Optimization Strategies for Enterprise Dashboards",excerpt:"Measurable techniques that improved load time and user experience across two enterprise applications.",category:"Performance",date:"2024-12-15",readTime:"6 min read",tags:["Performance","Angular","React"],demo:!0,body:["Dashboards are where performance goes to die \u2014 dozens of charts, tables, and live-updating widgets all competing for the main thread.","Measure first. If you cannot point at a number, you cannot claim an improvement. Lighthouse budgets and real-user monitoring make performance a tracked metric, not a feeling.","Cut the initial payload: lazy-loaded routes, deferred below-the-fold sections, and tree-shaken bundles. Then make updates cheap with OnPush rendering and memoized selectors.","Virtualize long lists, throttle expensive subscriptions, and never render what is not visible. Across two enterprise applications these patterns delivered measurable load-time improvements."]}],r=[{label:"Home",sectionId:"home",icon:"home"},{label:"Profile",sectionId:"photo",icon:"user"},{label:"Skills",sectionId:"skills",icon:"zap"},{label:"Craft",sectionId:"craft",icon:"layers"},{label:"Projects",sectionId:"projects",icon:"folder"},{label:"Education",sectionId:"education",icon:"graduation-cap"},{label:"Blog",sectionId:"blog",icon:"book"},{label:"Contact",sectionId:"contact",icon:"mail"}];export{e as a,t as b,i as c,a as d,n as e,o as f,r as g};
